from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from rest_framework.versioning import URLPathVersioning
from .models import CustomerOrder
from .serializers import OrderSerializer, LegacyOrderSummarySerializer

class OrderViewSet(viewsets.ModelViewSet):
    serializer_class = OrderSerializer
    permission_classes = [permissions.IsAuthenticated]
    versioning_class = URLPathVersioning

    def get_queryset(self):
        return CustomerOrder.objects.filter(customer=self.request.user)

    @action(detail=True, methods=["get"], url_path="legacy-summary")
    def legacy_summary(self, request, pk=None):
        instance = self.get_object()
        if request.version == "v1":
            serializer = LegacyOrderSummarySerializer(instance)
            return Response(serializer.data)
        return Response(self.get_serializer(instance).data)
